{"file_path":"src/address.js","content":"/**
 * Cell addresses. A column is one or two letters, `A` to `ZZ`, and a row is
 * one to three digits naming a row of at least 1.
 */

const ADDRESS = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Turn `A`, `Z`, `AA` ... `ZZ` into 1, 26, 27 ... 702. */
export function columnIndex(letters) {
  let index = 0
  for (const letter of letters.toUpperCase()) {
    index = index * 26 + (letter.charCodeAt(0) - 64)
  }
  return index
}

/** Turn 1, 26, 27 ... back into `A`, `Z`, `AA` ... */
export function columnName(index) {
  let name = ''
  let rest = index
  while (rest > 0) {
    const remainder = (rest - 1) % 26
    name = String.fromCharCode(65 + remainder) + name
    rest = (rest - remainder - 1) / 26
  }
  return name
}

/**
 * Read a word as an address. Returns `null` when the word is not one or two
 * letters and one to three digits naming a row of at least 1, which is an
 * address outside the addressable range rather than a failure to parse.
 */
export function parseAddress(word) {
  const match = ADDRESS.exec(word)
  if (match === null) return null
  const row = Number(match[2])
  if (row < 1) return null
  return { column: columnIndex(match[1]), row, name: match[1].toUpperCase() + String(row) }
}

/** The key a cell is held under: its upper-cased address. */
export function addressName(column, row) {
  return columnName(column) + String(row)
}

/** Order two addresses by column and then by row. */
export function compareAddresses(a, b) {
  if (a.column !== b.column) return a.column - b.column
  return a.row - b.row
}
"}

