{"file_path":"src/value.js","content":"/**
 * Values: a number, text, a boolean, or an error, and the coercions and
 * comparisons the sheet reads them through.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const num = (value) => ({ kind: 'number', value })
export const text = (value) => ({ kind: 'text', value })
export const bool = (value) => ({ kind: 'boolean', value })
export const err = (token) => ({ kind: 'error', value: token })

export const DIV0 = err('#DIV/0!')
export const REF = err('#REF!')
export const VALUE = err('#VALUE!')
export const CYCLE = err('#CYCLE!')
export const NAME = err('#NAME?')
export const ERR = err('#ERR!')

export const isError = (value) => value.kind === 'error'

/** A number that is not finite is the division error. */
export function finite(result) {
  return Number.isFinite(result) ? num(result) : DIV0
}

/**
 * Read a value in an arithmetic position: a boolean is 1 or 0 and text is the
 * value error. Errors pass through.
 */
export function toNumber(value) {
  if (value.kind === 'number') return value
  if (value.kind === 'boolean') return num(value.value ? 1 : 0)
  if (value.kind === 'error') return value
  return VALUE
}

/** Read a value as a condition: `TRUE` and a non-zero number are true. */
export function toCondition(value) {
  const asNumber = toNumber(value)
  if (isError(asNumber)) return asNumber
  return bool(asNumber.value !== 0)
}

const RANK = { number: 0, text: 1, boolean: 2 }

/** Compare two texts by code point rather than by UTF-16 code unit. */
function compareText(left, right) {
  const a = Array.from(left)
  const b = Array.from(right)
  const shared = Math.min(a.length, b.length)
  for (let index = 0; index < shared; index += 1) {
    const x = a[index].codePointAt(0)
    const y = b[index].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  if (a.length === b.length) return 0
  return a.length < b.length ? -1 : 1
}

/**
 * Order two values: numbers numerically, texts by code point, booleans with
 * false below true, and across kinds every number below every text and every
 * text below every boolean.
 */
export function compareValues(left, right) {
  if (left.kind !== right.kind) return RANK[left.kind] < RANK[right.kind] ? -1 : 1
  if (left.kind === 'text') return compareText(left.value, right.value)
  const x = left.kind === 'boolean' ? (left.value ? 1 : 0) : left.value
  const y = right.kind === 'boolean' ? (right.value ? 1 : 0) : right.value
  if (x === y) return 0
  return x < y ? -1 : 1
}

/** Print a number as JavaScript would after rounding to ten significant digits. */
export function formatNumber(value) {
  if (value === 0) return '0'
  return String(Number(value.toPrecision(10)))
}

/** Print a value the way `values` prints it. */
export function formatValue(value) {
  if (value.kind === 'number') return formatNumber(value.value)
  if (value.kind === 'boolean') return value.value ? 'TRUE' : 'FALSE'
  return value.value
}
"}

