chunk.argumentsDelta:
{"file_path":"src/formula.js","content":"/**
 * The formula grammar: numbers, cell addresses, ranges, the words `TRUE` and
 * `FALSE`, function calls, parentheses and the operators. Anything the grammar
 * does not accept makes the cell `#ERR!`, which is reported here by returning
 * `null` from `parseFormula`.
 */

const SPACE = new Set([' ', '\t'])
const DIGIT = /[0-9]/
const LETTER = /[A-Za-z]/

/** Split a formula body into tokens, or return `null` when a character is not one. */
export function tokenize(body) {
  const tokens = []
  let index = 0
  while (index < body.length) {
    const char = body[index]
    if (SPACE.has(char)) {
      index += 1
      continue
    }
    if (DIGIT.test(char)) {
      let end = index
      while (end < body.length && DIGIT.test(body[end])) end += 1
      if (body[end] === '.' && DIGIT.test(body[end + 1] ?? '')) {
        end += 1
        while (end < body.length && DIGIT.test(body[end])) end += 1
      }
      tokens.push({ type: 'number', text: body.slice(index, end) })
      index = end
      continue
    }
    if (LETTER.test(char)) {
      let end = index
      while (end < body.length && /[A-Za-z0-9]/.test(body[end])) end += 1
      tokens.push({ type: 'word', text: body.slice(index, end) })
      index = end
      continue
    }
    const two = body.slice(index, index + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      tokens.push({ type: 'op', text: two })
      index += 2
      continue
    }
    if ('^*/+-=<>'.includes(char)) {
      tokens.push({ type: 'op', text: char })
      index += 1
      continue
    }
    if ('(),:'.includes(char)) {
      tokens.push({ type: char, text: char })
      index += 1
      continue
    }
    return null
  }
  return tokens
}

export const FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

const COMPARISONS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.at = 0
  }

  peek(offset = 0) {
    return this.tokens[this.at + offset] ?? null
  }

  take() {
    const token = this.tokens[this.at]
    this.at += 1
    return token
  }

  isOp(text) {
    const token = this.peek()
    return token !== null && token.type === 'op' && token.text === text
  }

  // expression := comparison, grouping to the left
  expression() {
    let left = this.additive()
    for (;;) {
      const token = this.peek()
      if (token === null || token.type !== 'op' || !COMPARISONS.has(token.text)) return left
      this.take()
      const right = this.additive()
      left = { type: 'binary', op: token.text, left, right }
    }
  }

  additive() {
    let left = this.multiplicative()
    while (this.isOp('+') || this.isOp('-')) {
      const op = this.take().text
      const right = this.multiplicative()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  multiplicative() {
    let left = this.power()
    while (this.isOp('*') || this.isOp('/')) {
      const op = this.take().text
      const right = this.power()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  // `^` groups to the right and a leading sign binds tighter than it
  power() {
    const left = this.unary()
    if (this.isOp('^')) {
      this.take()
      const right = this.power()
      return { type: 'binary', op: '^', left, right }
    }
    return left
  }

  unary() {
    if (this.isOp('-') || this.isOp('+')) {
      const op = this.take().text
      return { type: 'unary', op, operand: this.unary() }
    }
    return this.primary()
  }

  primary() {
    const token = this.peek()
    if (token === null) throw new SyntaxError('unexpected end of formula')
    if (token.type === 'number') {
      this.take()
      return { type: 'number', value: Number(token.text) }
    }
    if (token.type === '(') {
      this.take()
      const inner = this.expression()
      if (this.peek() === null || this.peek().type !== ')') throw new SyntaxError('missing )')
      this.take()
      return { type: 'group', inner }
    }
    if (token.type === 'word') {
      this.take()
      const next = this.peek()
      if (next !== null && next.type === '(') return this.call(token.text)
      if (next !== null && next.type === ':') {
        this.take()
        const end = this.peek()
        if (end === null || end.type !== 'word') throw new SyntaxError('bad range')
        this.take()
        return { type: 'range', from: token.text, to: end.text }
      }
      const upper = token.text.toUpperCase()
      if (upper === 'TRUE' || upper === 'FALSE') return { type: 'boolean', value: upper === 'TRUE' }
      return { type: 'ref', word: token.text }
    }
    throw new SyntaxError('unexpected token')
  }

  call(name) {
    this.take() // the '('
    const args = []
    if (this.peek() !== null && this.peek().type === ')') {
      this.take()
      return { type: 'call', name: name.toUpperCase(), args }
    }
