{"file_path":"src/sheet.js","content":"/**
 * Reading a sheet from its text: one cell to a line, `<address> <content>`,
 * with blank lines and lines beginning with `#` ignored.
 */

import { compareAddresses, parseAddress } from './address.js'

export class SheetError extends Error {}

/**
 * Split the input into lines, dropping the empty tail a trailing newline
 * leaves, and read a cell from each line that declares one.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let index = 0; index < lines.length; index += 1) {
    const number = index + 1
    const line = lines[index].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end += 1
    const word = line.slice(0, end)
    let rest = end
    while (rest < line.length && (line[rest] === ' ' || line[rest] === '\t')) {
      rest += 1
      break
    }
    const content = line.slice(rest)

    const address = parseAddress(word)
    if (address === null) {
      throw new SheetError(`error: line ${number}: invalid cell address ${word}`)
    }
    if (cells.has(address.name)) {
      throw new SheetError(`error: line ${number}: cell ${address.name} is declared twice`)
    }
    cells.set(address.name, { address, content })
  }
  return cells
}

/** The declared cells in ascending column and then ascending row order. */
export function orderedCells(cells) {
  return [...cells.values()].sort((a, b) => compareAddresses(a.address, b.address))
}
"}

