  argumentValues(node) {
    if (node.type !== 'range') return [this.evaluate(node)]
    const cells = rangeCells(node)
    if (cells === null) return [REF]
    return cells.map((cell) => this.valueAt(cell.name))
  }

  call(node) {
    const { name, args } = node
    if (name === 'IF') {
      if (args.length !== 3) return ERR
      const condition = toCondition(this.argumentValues(args[0])[0])
      if (isError(condition)) return condition
      return this.argumentValues(args[condition.value ? 1 : 2])[0]
    }
    if (name === 'ABS') {
      if (args.length !== 1) return ERR
    } else if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) {
      if (args.length < 1) return ERR
    } else {
      return NAME
    }

    const values = []
    for (const arg of args) values.push(...this.argumentValues(arg))
    for (const value of values) {
      if (isError(value)) return value
    }

    if (name === 'COUNT') {
      return num(values.filter((value) => value.kind === 'number').length)
    }

    const numbers = []
    for (const value of values) {
      const asNumber = toNumber(value)
      if (isError(asNumber)) return asNumber
      numbers.push(asNumber.value)
    }
    switch (name) {
      case 'ABS': return finite(Math.abs(numbers[0]))
      case 'SUM': return finite(numbers.reduce((total, one) => total + one, 0))
      case 'MIN': return finite(Math.min(...numbers))
      case 'MAX': return finite(Math.max(...numbers))
      default: {
        const total = numbers.reduce((sum, one) => sum + one, 0)
        return numbers.length === 0 ? DIV0 : finite(total / numbers.length)
      }
    }
  }
}

/**
 * The distinct cells a cell's content names directly, ranges expanded and only
 * addresses inside the addressable range named.
 */
export function dependencies(cell) {
  const parsed = contentOf(cell)
  if (parsed.kind !== 'formula') return []
  const found = new Map()
  const walk = (node) => {
    switch (node.type) {
      case 'ref': {
        const address = parseAddress(node.word)
        if (address !== null) found.set(address.name, address)
        break
      }
      case 'range': {
        const cells = rangeCells(node)
        if (cells !== null) for (const one of cells) found.set(one.name, one)
        break
      }
      case 'group':
        walk(node.inner)
        break
      case 'unary':
        walk(node.operand)
        break
      case 'binary':
        walk(node.left)
        walk(node.right)
        break
      case 'call':
        for (const arg of node.args) walk(arg)
        break
      default:
        break
    }
  }
  walk(parsed.tree)
  return [...found.values()].sort(compareAddresses).map((address) => address.name)
}
"}

