      const order = compareValues(left, right)
      switch (node.op) {
        case '=': return bool(order === 0)
        case '<>': return bool(order !== 0)
        case '<': return bool(order < 0)
        case '<=': return bool(order <= 0)
        case '>': return bool(order > 0)
        default: return bool(order >= 0)
      }
    }

    const x = toNumber(left)
    if (isError(x)) return x
    const y = toNumber(right)
    if (isError(y)) return y
    switch (node.op) {
      case '+': return finite(x.value + y.value)
      case '-': return finite(x.value - y.value)
      case '*': return finite(x.value * y.value)
      case '/': return y.value === 0 ? DIV0 : finite(x.value / y.value)
      default: return finite(x.value ** y.value)
    }
