 * Evaluating the sheet: what a literal means, what a formula computes, and
 * which cells a cell's content names.
 */

import { addressName, compareAddresses, parseAddress } from './address.js'
import { parseFormula, rangesArePlaced } from './formula.js'
import {
  CYCLE,
  DIV0,
  ERR,
  ERROR_TOKENS,
  NAME,
  REF,
  bool,
  compareValues,
  err,
  finite,
  isError,
  num,
  text,
  toCondition,
  toNumber,
} from './value.js'

const NUMBER_LITERAL = /^-?[0-9]+(\.[0-9]+)?$/

/** Read a literal: empty is zero, a number is that number, an error token is that error. */
export function readLiteral(content) {
  if (content === '') return num(0)
  if (NUMBER_LITERAL.test(content)) return num(Number(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

/** The parsed form of a cell's content, computed once per cell. */
function contentOf(cell) {
  if (cell.parsed !== undefined) return cell.parsed
  if (cell.content.startsWith('=')) {
    const tree = parseFormula(cell.content.slice(1))
    cell.parsed = tree === null ? { kind: 'broken' } : { kind: 'formula', tree }
  } else {
    cell.parsed = { kind: 'literal', value: readLiteral(cell.content) }
  }
  return cell.parsed
}

/** Expand a range into the cells it covers, in column and then row order. */
function rangeCells(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (from === null || to === null) return null
  const cells = []
  const lowColumn = Math.min(from.column, to.column)
  const highColumn = Math.max(from.column, to.column)
  const lowRow = Math.min(from.row, to.row)
  const highRow = Math.max(from.row, to.row)
  for (let column = lowColumn; column <= highColumn; column += 1) {
    for (let row = lowRow; row <= highRow; row += 1) {
      cells.push({ column, row, name: addressName(column, row) })
    }
  }
  return cells
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.values = new Map()
    this.visiting = new Set()
  }

  /** The value of the cell at an upper-cased address; an undeclared cell is zero. */
  valueAt(name) {
    if (this.values.has(name)) return this.values.get(name)
    const cell = this.cells.get(name)
    if (cell === undefined) return num(0)
    if (this.visiting.has(name)) return CYCLE
    this.visiting.add(name)
    let value
    try {
      value = this.evaluateCell(cell)
    } finally {
      this.visiting.delete(name)
    }
    this.values.set(name, value)
    return value
  }

  evaluateCell(cell) {
    const parsed = contentOf(cell)
    if (parsed.kind === 'literal') return parsed.value
    if (parsed.kind === 'broken') return ERR
    if (!rangesArePlaced(parsed.tree)) return ERR
    return this.evaluate(parsed.tree)
