{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { Evaluator, dependencies } from './evaluate.js'
import { SheetError, orderedCells, parseSheet } from './sheet.js'
import { formatValue } from './value.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'values' && mode !== 'deps') fail('error: usage: cli.js values|deps')

  let cells
  try {
    cells = parseSheet(readStdin())
  } catch (error) {
    if (error instanceof SheetError) fail(error.message)
    throw error
  }

  const ordered = orderedCells(cells)
  const lines = []
  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const cell of ordered) {
      lines.push(`${cell.address.name}=${formatValue(evaluator.valueAt(cell.address.name))}`)
    }
  } else {
    for (const cell of ordered) {
      const names = dependencies(cell)
      lines.push(`${cell.address.name}:${names.map((name) => ` ${name}`).join('')}`)
    }
  }
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

main(process.argv.slice(2))
"}

